    new_entries = ",\n  " + g1_str + ",\n  " + g2_str + ",\n  " + g3_str + "\n"

    updated_content = content[:idx].rstrip() + new_entries + "];\n"

    with open("src/data/guides-data.ts", "w", encoding="utf-8") as f:
        f.write(updated_content)

    print("Successfully appended 3 new December 01, 2026 guides to src/data/guides-data.ts!")
    return True

